from Crypto.Util.number import getPrime
from secrets import choice, randbelow
from math import gcd


flag = b'EYCC{flagwashere}'
bits = 512
e = 65537
half = bits // 2

while True:
    p = getPrime(half)
    q = getPrime(half)
    n = p * q

    if n.bit_length() == bits and gcd(e, (p - 1) * (q - 1)) == 1:
        break

size = bits // 8
padding = bytes(choice(range(1, 256)) for _ in range(size - 3 - len(flag)))
block = b"\x00\x02" + padding + b"\x00" + flag
m = int.from_bytes(block, "big")
c = pow(m, e, n)

bound = 1 << (bits - 16)
ell = int(1.3 * bits / 16)
rs = []

while len(rs) < ell:
    r = randbelow(n - 1) + 1

    if 2 * bound <= r * m % n < 3 * bound:
        rs.append(r)

print(f"n = {n}")
print(f"c = {c}")
print(f"rs = {rs}")

